require_once __DIR__.'/../config/bootstrap.php';require_admin();$pid=(int)($_GET['product_id']??0);$s=db()->prepare('SELECT name FROM products WHERE id=?');$s->execute([$pid]);$product=$s->fetch();if(!$product){http_response_code(404);exit('Product not found');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!isset($_FILES['image'])||$_FILES['image']['error']!==UPLOAD_ERR_OK){$error='Choose an image file.';}else{$tmp=$_FILES['image']['tmp_name'];$size=(int)$_FILES['image']['size'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if($size>4*1024*1024||!isset($allowed[$mime])){$error='Only JPG, PNG or WebP images up to 4MB are allowed.';}else{$dir=__DIR__.'/../storage/uploads';if(!is_dir($dir))mkdir($dir,0755,true);$filename=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(move_uploaded_file($tmp,$dir.'/'.$filename)){$path='/storage/uploads/'.$filename;$alt=trim((string)($_POST['alt_text']??$product['name']));$s=db()->prepare('INSERT INTO product_images(product_id,image_path,alt_text,sort_order,is_primary) VALUES(?,?,?,?,?)');$s->execute([$pid,$path,$alt,0,(int)empty($_POST['not_primary'])]);}else{$error='Unable to store the uploaded image.';}}}}$s=db()->prepare('SELECT * FROM product_images WHERE product_id=? ORDER BY is_primary DESC,id DESC');$s->execute([$pid]);$images=$s->fetchAll();$pageTitle='Product images — Ikki';require __DIR__.'/../includes/header.php';?><div class="admin-shell"><h1 class="page-title">Images · <?=e($product['name'])?></h1><nav class="admin-nav"><a href="/admin/">Dashboard</a><a href="/admin/products.php">Products</a></nav><?php if($error):?><p class="notice"><?=e($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data" class="site-form"><?=csrf_field()?><label class="field-label">Image (JPG, PNG, WebP; max 4MB)</label><input class="field" type="file" name="image" accept="image/jpeg,image/png,image/webp" required><label class="field-label">Alt text</label><input class="field" name="alt_text" value="<?=e($product['name'])?>"><label><input type="checkbox" name="not_primary" value="1"> Do not set as primary</label><p><button class="btn">Upload image</button></p></form><div class="product-grid"><?php foreach($images as $im):?><div><img src="<?=e($im['image_path'])?>" alt="<?=e($im['alt_text'])?>" style="width:100%;aspect-ratio:1;object-fit:cover"><p class="muted"><?=e($im['alt_text'])?> <?=((int)$im['is_primary']?'· Primary':'')?></p></div><?php endforeach;?></div></div><?php require __DIR__.'/../includes/footer.php';?>